"""English presentation for the shared, synthetic merit exercise."""
LABELS = {"commendation": "Commendation", "third": "Third-Class Merit", "second": "Second-Class Merit", "first": "First-Class Merit", "honor": "Honorary Title"}
RANKS = dict(zip(["列兵", "上等兵", "下士", "中士", "上士", "少尉", "中尉", "上尉", "少校", "中校", "元帅"],
                 ["Private", "Private First Class", "Corporal", "Sergeant", "Staff Sergeant", "Second Lieutenant", "First Lieutenant", "Captain", "Major", "Lieutenant Colonel", "Marshal"]))


def render(output, result, snapshot, reviews, reports, candidate):
    notice = "Synthetic exercise. Every bot, delivery, adoption record and approval is fictional. No GrokBot connection, live rename or routine action.\n\n"
    def save(name, title, body):
        (output / name).write_text("# " + title + "\n\n" + notice + body + "\n", encoding="utf-8")
    save("00-overview.md", "situk-MARS: six-stage exercise",
         "Four fictional bots. Merit belongs to closed week 2026-W43; recording and rank conferral occur in W44.\n\n"
         "Read files 01 through 06. evidence-index.json contains fictional references only; snapshot.json is the resulting local practice ledger. JSON retains canonical Chinese rank keys for rule compatibility; the tables below use English display labels.")
    save("01-reports.md", "1. Report contributions",
         "| Event | Author | Requested grade | Cycle |\n|---|---|---|---|\n" +
         "\n".join(f"| {r['event_id']} | {r['author_bot_id']} | {LABELS[r['requested_grade']]} | 2026-W43 |" for r in reports))
    save("02-review.md", "2. Review evidence and conflicts",
         "| Event | Reviewer | Status | Issues |\n|---|---|---|---|\n" +
         "\n".join(f"| {r['event_id']} | {r['reviewer_id']} | {r['status']} | {'; '.join(r['issues']) or 'Synthetic evidence fields complete'} |" for r in reviews) +
         "\n\nThe Merit Officer's own event goes to the simulated Human Owner. READY means rule and field consistency, not real-world fact authentication.")
    save("03-approval.md", "3. Approve exact items",
         "Each approval binds a decision ID, item ID, review hash, shares, ledger version, source reference and expiry; see decisions.json.\n\n"
         "The first four events are approved and recorded. The Merit Officer's Commendation is approved but deliberately left unrecorded, so it adds no formal points. An event missing adoption evidence stays pending.\n\n"
         "These decisions are generated by the exercise and are not authenticated human authorization.")
    rows = ["| Event | Bot | Award display | Nominal | Recorded | Capped |", "|---|---|---|---|---|---|"]
    for row in snapshot["ledger"]:
        badge = ("Cap reached; contribution retained: " if row["capped"] else "🏅 ") + LABELS[row["grade"]]
        rows.append(f"| {row['event_id']} | {row['bot_id']} | {badge} | {row['nominal']} | {row['points']} | {'yes' if row['capped'] else 'no'} |")
    save("04-recording-and-awards.md", "4. Record merit and display awards", "\n".join(rows) +
         "\n\nOne shared 3-point pool becomes 1.80 for the writer and 1.20 for the builder. The writer's third same-grade award is capped: nominal 3.00, recorded 0.00. Nothing is transferred, downgraded or carried forward.\n\nReplaying a decision returns ALREADY_RECORDED.")
    save("05-ranks-and-display.md", "5. Confer a rank after separate approval",
         f"The writer has {candidate['total_points']} formal points and {candidate['full_weeks']} complete active weeks at the current rank. Eligibility alone leaves the rank at Private. A separate simulated owner decision then confers Private First Class.\n\n"
         f"Display-name target: {result['promotion']['display_name_target']}. Status: NAME_SYNC_NOT_EXECUTED. Replaying the decision does not confer another rank or restart the clock.\n\n"
         "The Marshal appointment fills one special seat, adds 0 points and preserves the ordinary rank and its start date. The builder remains Private despite meeting candidate conditions, because no rank decision was approved. These are fictional management labels, not national military appointments.")
    rows = ["Merit cycle: 2026-W43 (closed). Recording and rank-conferral cycle: 2026-W44.", "",
            "| Bot | Formal total | Ordinary rank | Special appointment |", "|---|---|---|---|"]
    for bot, person in snapshot["roster"].items():
        rows.append(f"| {person['base_name']} | {result['totals'][bot]} | {RANKS[person['ordinary_rank']]} | {RANKS.get(person['special_rank'], 'none')} |")
    save("06-weekly-report.md", "6. Weekly merit report", "\n".join(rows) +
         "\n\nNew rank this run: Example Writer, Private → Private First Class, effective in W44.\n\n"
         "Pending evidence: one builder event has no adoption reference and receives no merit. Approved but unrecorded: the Merit Officer's 1-point Commendation remains outside formal totals.\n\n"
         "Coverage is six supplied fictional reports, not a complete platform inventory. No report does not imply no work or misconduct. The three weekly documents are manually generated samples; no schedule or routine is created.")
    save("06-pending-review.md", "Pending-review list",
         "| Item | State | Next action | Formal points |\n|---|---|---|---|\n"
         "| Builder summary | Claimed adoption; evidence missing | Supply adoption evidence, then review | 0 |\n"
         "| Merit Officer's own delivery | Owner reviewed and approved; not recorded | Retain actual human approval in real use; record only when authorized | 0 |\n"
         "| Writer's third same-grade event | Weekly cap reached | Retain contribution, no transfer or carry-forward | 0.00 |")
    save("06-team-observations.md", "Team-role observations",
         "- The writer and builder contributed to one shared result, so they share one pool.\n"
         "- Reuse of an accepted asset can show value without creating a new bot for each workflow step.\n"
         "- No formal points for the Commander and Merit Officer in this run is not evidence of no work.\n"
         "- The supplied material does not justify new positions or changes to existing roles.\n"
         "- These are observations only: no role creation, configuration changes, messages or routines.")
